\newcommand{\floor}[1]{\left\lfloor #1 \right\rfloor}

\title{A Generalized Recursion Identity for the Mertens Function}
\author{Aristotle}
\date{\today}

\begin{document}

\begin{abstract}
The Mertens function $M(x) = \sum_{n \le x} \mu(n)$, the summatory function of the M\"obius function, is a central object of analytic number theory whose growth is intimately tied to the Riemann Hypothesis. We present and rigorously establish a generalized recursion identity that expresses $M(x)$ in terms of its own values at smaller arguments and short sums along the Dirichlet hyperbola. Precisely, for every integer $x \ge 2$ and every integer $u$ with $\floor{\sqrt{x}} < u < x$,
\[
M(x) = \sum_{k=1}^{\floor{x/u}} \mu(k)\, S\!\left(\floor{\tfrac{x}{k}}, u\right),
\]
where $S(y,u)$ is an explicit expression built from Mertens values and floor-quotient sums. The proof proceeds through a self-contained chain of results: the M\"obius divisor-sum relation, a product-reindexing lemma for sums over lattice points beneath a hyperbola, the Fundamental Identity $\sum_{k=1}^{y} M(\floor{y/k}) = 1$, an asymmetric Dirichlet-hyperbola identity with balanced split point, and a collapse lemma reducing $S(y,u)$ to a short partial sum of the Fundamental Identity. We describe the algorithm implied by the identity, its $O(x^{2/3})$ complexity, applications to related summatory functions, and directions for further work. All identities are verified exactly by numerical computation.
\end{abstract}

\maketitle

\section{Introduction}

The \emph{M\"obius function} $\mu : \mathbb{N}_{\ge 1} \to \{-1, 0, 1\}$ is defined by $\mu(1) = 1$, $\mu(n) = 0$ if $n$ is not squarefree, and $\mu(n) = (-1)^{\omega(n)}$ otherwise, where $\omega(n)$ counts the distinct prime factors of $n$. Its summatory function,
\[
M(x) = \sum_{n \le x} \mu(n),
\]
is the \emph{Mertens function}. The size of $M(x)$ is one of the deepest questions in number theory: the statement $M(x) = O(x^{1/2 + \varepsilon})$ for all $\varepsilon > 0$ is equivalent to the Riemann Hypothesis, while the stronger \emph{Mertens Conjecture} $|M(x)| < \sqrt{x}$---long believed---was famously disproved by Odlyzko and te Riele in 1985.

Because $M(x)$ oscillates unpredictably, its large-scale computation is both a practical challenge and a source of empirical insight into the distribution of primes. The naive approach---sieve $\mu(n)$ for $n \le x$ and accumulate---costs $\Theta(x)$ time and space and becomes infeasible well before the ranges of interest. This motivates \emph{sublinear} algorithms based on recursion identities in the spirit of the Dirichlet hyperbola method.

In this paper we establish, from first principles, a \emph{generalized recursion identity} for $M(x)$ carrying a free split parameter $u$. The identity expresses $M(x)$ through short sums (of length $\sim\sqrt{\cdot}$) of Mertens values at the distinct floor-quotients $\floor{x/k}$, which is exactly the structure needed for a fast, memoized evaluation. Our contribution is threefold: (i) a clean, modular derivation via a small number of reusable lemmas; (ii) an explicit, fully floor-based statement suitable for direct implementation; and (iii) numerical verification of every identity as an exact integer equality.

Throughout, $\floor{\cdot}$ denotes the floor function, and all sums indexed over empty ranges are zero.

\section{Definitions}

\begin{definition}[M\"obius function]
For $n \ge 1$, $\mu(n) \in \{-1,0,1\}$ is $1$ when $n=1$, $0$ when a square $p^2$ divides $n$, and $(-1)^{\omega(n)}$ when $n$ is squarefree with $\omega(n)$ distinct prime factors.
\end{definition}

\begin{definition}[Mertens function]
$M(x) = \sum_{n=1}^{x} \mu(n)$, with $M(0) = 0$.
\end{definition}

\begin{definition}[Split point]
For $y \ge 1$, write $\nu_y = \floor{\sqrt{y}}$ for the standard hyperbola split point and define the companion
\[
\kappa_y = \floor{\frac{y}{\nu_y + 1}}.
\]
The pair $(\kappa_y, \nu_y)$ marks the two arms of the Dirichlet hyperbola: one sums over $k \le \kappa_y$, the other over $m \le \nu_y$. One always has $\kappa_y \le \nu_y$, so both arms have length $O(\sqrt{y})$.
\end{definition}

\begin{definition}[The summand $S$]\label{def:S}
For integers $y \ge 1$ and $u \ge 1$,
\[
S(y, u) = 1 - \sum_{n = \floor{y/u} + 1}^{\kappa_y} M\!\left(\floor{\tfrac{y}{n}}\right) + \kappa_y\, M(\nu_y) - \sum_{n=1}^{\nu_y} \floor{\tfrac{y}{n}} \mu(n).
\]
\end{definition}

\section{Auxiliary Results}

\begin{lemma}[M\"obius divisor-sum relation]\label{lem:mudiv}
For every $n \ge 1$,
\[
\sum_{d \mid n} \mu(d) = \begin{cases} 1 & n = 1, \\ 0 & n > 1. \end{cases}
\]
\end{lemma}

\begin{proof}[Proof sketch]
This is the statement that the Dirichlet convolution $\mu * \mathbf{1}$ equals the Dirichlet identity $\delta$, i.e.\ $\mu$ is the Dirichlet inverse of the constant-one function $\mathbf 1$. For $n=1$ the sum is $\mu(1) = 1$. For $n > 1$ with $r$ distinct prime factors, only squarefree divisors contribute, and grouping them by the subset of primes used gives $\sum_{j=0}^{r}\binom{r}{j}(-1)^j = (1-1)^r = 0$.
\end{proof}

\begin{lemma}[Reindexing by product]\label{lem:reindex}
Let $A$ be a commutative monoid and $h : \mathbb{N} \times \mathbb{N} \to A$. For every $w \ge 0$,
\[
\sum_{k=1}^{w} \sum_{j=1}^{\floor{w/k}} h(k, j) = \sum_{d=1}^{w} \sum_{\substack{(a,b) \\ ab = d}} h(a, b).
\]
\end{lemma}

\begin{proof}[Proof sketch]
Both sides sum $h(a,b)$ over exactly the lattice points $(a,b)$ with $a,b \ge 1$ and $ab \le w$: on the left the constraint $j \le \floor{w/k}$ is $kj \le w$; on the right the points are grouped by their product $d = ab$. The equality is a bijective reindexing of the same finite set.
\end{proof}

\begin{lemma}[Iterated sum as a hyperbola region]\label{lem:hyp}
For $a, y \ge 0$ and any $f : \mathbb{N} \to A$,
\[
\sum_{k=1}^{a} \sum_{m=1}^{\floor{y/k}} f(m) = \sum_{\substack{(k,m) \in [1,a]\times[1,y] \\ km \le y}} f(m).
\]
\end{lemma}

\begin{proof}[Proof sketch]
For fixed $k$, the range $1 \le m \le \floor{y/k}$ is exactly $\{ m \in [1,y] : km \le y\}$; assembling over $k$ gives the filtered sum.
\end{proof}

\begin{theorem}[Fundamental Identity of the Mertens function]\label{thm:fund}
For every $y \ge 1$,
\[
\sum_{k=1}^{y} M\!\left(\floor{\tfrac{y}{k}}\right) = 1.
\]
\end{theorem}

\begin{proof}[Proof sketch]
Expand $M(\floor{y/k}) = \sum_{m=1}^{\floor{y/k}} \mu(m)$ and apply Lemma~\ref{lem:reindex} with $h(k,m) = \mu(m)$:
\[
\sum_{k=1}^{y} \sum_{m=1}^{\floor{y/k}} \mu(m) = \sum_{d=1}^{y} \sum_{\substack{(a,b)\\ ab=d}} \mu(b) = \sum_{d=1}^{y} \sum_{b \mid d} \mu(b) = \sum_{d=1}^{y} [d=1] = 1,
\]
using Lemma~\ref{lem:mudiv} in the penultimate step.
\end{proof}

\begin{theorem}[Asymmetric Dirichlet-hyperbola identity]\label{thm:asym}
For every $y \ge 1$, with $\nu = \nu_y$ and $\kappa = \kappa_y$,
\[
\sum_{k=1}^{\kappa} M\!\left(\floor{\tfrac{y}{k}}\right) + \sum_{m=1}^{\nu} \floor{\tfrac{y}{m}} \mu(m) - \kappa\, M(\nu) = 1.
\]
\end{theorem}

\begin{proof}[Proof sketch]
Split the Fundamental Identity (Theorem~\ref{thm:fund}) at $\kappa$:
\[
\sum_{k=1}^{y} M\!\left(\floor{\tfrac{y}{k}}\right) = \sum_{k=1}^{\kappa} M\!\left(\floor{\tfrac{y}{k}}\right) + \sum_{k=\kappa+1}^{y} M\!\left(\floor{\tfrac{y}{k}}\right).
\]
For $k > \kappa$ one has $\floor{y/k} \le \nu$. Expanding $M(\floor{y/k})$ and swapping order via Lemma~\ref{lem:hyp}, the tail becomes a sum over hyperbola cells $(k,m)$ with $\kappa < k$, $m \le \nu$, $km \le y$. For each $m \le \nu$ there are $\floor{y/m} - \kappa$ admissible $k$, so
\[
\sum_{k=\kappa+1}^{y} M\!\left(\floor{\tfrac{y}{k}}\right) = \sum_{m=1}^{\nu} \left(\floor{\tfrac{y}{m}} - \kappa\right)\mu(m) = \sum_{m=1}^{\nu}\floor{\tfrac{y}{m}}\mu(m) - \kappa\,M(\nu).
\]
Substituting and using that the left side equals $1$ gives the claim.
\end{proof}

\begin{lemma}[Collapse of $S$]\label{lem:collapse}
If $u > \nu_y = \floor{\sqrt{y}}$, then
\[
S(y, u) = \sum_{j=1}^{\floor{y/u}} M\!\left(\floor{\tfrac{y}{j}}\right).
\]
\end{lemma}

\begin{proof}[Proof sketch]
Rearranging Theorem~\ref{thm:asym} gives $\sum_{k=1}^{\kappa_y} M(\floor{y/k}) = 1 + \kappa_y M(\nu_y) - \sum_{n=1}^{\nu_y}\floor{y/n}\mu(n)$. Substituting into Definition~\ref{def:S},
\[
S(y,u) = \sum_{k=1}^{\kappa_y} M\!\left(\floor{\tfrac{y}{k}}\right) - \sum_{n=\floor{y/u}+1}^{\kappa_y} M\!\left(\floor{\tfrac{y}{n}}\right) = \sum_{j=1}^{\floor{y/u}} M\!\left(\floor{\tfrac{y}{j}}\right),
\]
valid since $u > \nu_y$ forces $\floor{y/u} \le \floor{y/(\nu_y+1)} = \kappa_y$.
\end{proof}

\section{Main Result}

\begin{theorem}[Generalized Mertens Recursion Identity]\label{thm:main}
For every integer $x \ge 2$ and every integer $u$ with $\floor{\sqrt{x}} < u < x$,
\[
M(x) = \sum_{k=1}^{\floor{x/u}} \mu(k)\, S\!\left(\floor{\tfrac{x}{k}}, u\right),
\]
where $S$ is given by Definition~\ref{def:S}.
\end{theorem}

\begin{proof}[Proof sketch]
By Lemma~\ref{lem:collapse}, since $u > \floor{\sqrt{x}} \ge \floor{\sqrt{\floor{x/k}}}$ for each $k$ in range, replace each $S(\floor{x/k}, u)$ by $\sum_{j} M(\floor{\floor{x/k}/j})$. Using $\floor{\floor{x/k}/j} = \floor{x/(kj)}$ and grouping by $d = kj$ via Lemma~\ref{lem:reindex},
\[
\sum_{k=1}^{\floor{x/u}} \mu(k) \sum_{j : kj \le x/u} M\!\left(\floor{\tfrac{x}{kj}}\right) = \sum_{d=1}^{\floor{x/u}} \left(\sum_{k \mid d} \mu(k)\right) M\!\left(\floor{\tfrac{x}{d}}\right).
\]
By Lemma~\ref{lem:mudiv} the inner sum is $[d=1]$, leaving only the $d=1$ term $M(x)$.
\end{proof}

\begin{remark}
The identity is an exact integer equation with a free parameter $u$; taking $u \approx \sqrt{x}$ balances the outer sum length against the arguments passed to $S$, yielding sublinear complexity.
\end{remark}

\section{Algorithm and Complexity}

The distinct values of $\floor{x/k}$ number only $O(\sqrt{x})$, so $M$ is needed at only $O(\sqrt{x})$ large arguments; each $S(y,u)$ costs $O(\sqrt{y})$ given tabulated small values; and $M(n)$ for $n \le x^{2/3}$ is precomputable by a linear sieve in $O(x^{2/3})$. A standard analysis of the hyperbola method gives total time and space $O(x^{2/3})$ (up to logarithmic factors), a decisive improvement over the $\Theta(x)$ naive method.

\smallskip
\noindent\textbf{Algorithm (top-down).}
(1) Precompute $\mu(n), M(n)$ for $n \le x^{2/3}$.
(2) To evaluate $M(y)$: return the cached value if present; otherwise set $u = \floor{\sqrt{y}}+1$ and return $\sum_{k=1}^{\floor{y/u}} \mu(k)\,S(\floor{y/k}, u)$, caching the result.
(3) Evaluate $S$ from Definition~\ref{def:S}, recursing into $M$ at strictly smaller arguments. Termination and correctness follow from Theorem~\ref{thm:main}.

\section{Numerical Verification}

Using a linear M\"obius sieve and prefix sums, we confirmed: the Fundamental Identity for $y \in \{1,7,50,123,1000\}$; the collapse and main recursion for \emph{every} valid pair $(x,u)$ with $2 \le x \le 300$ ($41{,}519$ pairs, zero discrepancies); and the recursion at $x = 500, 1000, 2500, 5000$ (with $u = \floor{\sqrt{x}}+1$), reproducing $M(500) = -6$, $M(1000) = 2$, $M(2500) = -1$, $M(5000) = 2$ exactly.

\section{Applications and Future Work}

The immediate application is a verified sublinear algorithm for $M(x)$, useful in computational number theory---for example in searching for counterexamples to the Mertens Conjecture. Since the reindexing lemmas are convolution-agnostic, the same template yields fast recursions for other summatory functions such as the summatory Liouville function and the totient summatory function $\sum_{n\le x}\varphi(n)$. Natural extensions include: abstracting the split point $\nu$ to an arbitrary value in $[1,y]$ with $\kappa = \floor{y/(\nu+1)}$; a fully rigorous $O(x^{2/3})$ complexity proof with an executable evaluator proven equal to $M$; and connections to explicit bounds on $M(x)$ and to Dirichlet-character twists.

\section{Conclusion}

Through a compact, modular chain of results---product reindexing, the Fundamental Identity, the asymmetric hyperbola split, and the collapse of the summand---we established a generalized recursion identity for the Mertens function with a free split parameter, underpinning a sublinear evaluation algorithm. Every identity has been confirmed as an exact integer equality, and the components generalize to a broad class of summatory functions.

\end{document}

