from math import isqrt


def moebius_sieve(limit: int) -> list[int]:
    """Linear sieve of the Moebius function mu[0..limit] (mu[0] unused)."""
    mu: list[int] = [0] * (limit + 1)
    if limit >= 1:
        mu[1] = 1
    primes: list[int] = []
    comp: list[bool] = [False] * (limit + 1)
    for i in range(2, limit + 1):
        if not comp[i]:
            primes.append(i)
            mu[i] = -1
        for p in primes:
            if i * p > limit:
                break
            comp[i * p] = True
            if i % p == 0:
                mu[i * p] = 0
                break
            mu[i * p] = -mu[i]
    return mu


def mertens_table(mu: list[int]) -> list[int]:
    """Prefix sums M[x] = sum_{n<=x} mu(n)."""
    M: list[int] = [0] * len(mu)
    acc = 0
    for x in range(1, len(mu)):
        acc += mu[x]
        M[x] = acc
    return M


def kappa(y: int) -> int:
    return y // (isqrt(y) + 1)


def S_direct(y: int, u: int, M: list[int], mu: list[int]) -> int:
    nu, k = isqrt(y), kappa(y)
    hyper = sum(M[y // n] for n in range(y // u + 1, k + 1))
    sqrt_term = sum((y // n) * mu[n] for n in range(1, nu + 1))
    return 1 - hyper + k * M[nu] - sqrt_term


def S_collapsed(y: int, u: int, M: list[int]) -> int:
    return sum(M[y // j] for j in range(1, y // u + 1))


def rhs(x: int, u: int, M: list[int], mu: list[int]) -> int:
    return sum(mu[k] * S_direct(x // k, u, M, mu) for k in range(1, x // u + 1))


def main() -> None:
    LIMIT = 300
    mu = moebius_sieve(LIMIT)
    M = mertens_table(mu)
    checked = failures = 0
    for x in range(2, LIMIT + 1):
        for u in range(isqrt(x) + 1, x):
            checked += 1
            if S_direct(x, u, M, mu) != S_collapsed(x, u, M):
                failures += 1
            if rhs(x, u, M, mu) != M[x]:
                failures += 1
    print(f"checked {checked} pairs; failures = {failures}")


if __name__ == "__main__":
    main()

