        M[x] = acc
    return M


class MertensEvaluator:
    def __init__(self, x: int) -> None:
        self.small = max(int(round(x ** (2 / 3))), isqrt(x) + 2)
        self.mu = moebius_sieve(self.small)
        self.Msmall = mertens_table(self.mu)
        self.cache: dict[int, int] = {}

    def M(self, y: int) -> int:
        if y <= self.small:
            return self.Msmall[y]
        if y in self.cache:
            return self.cache[y]
        u = isqrt(y) + 1
        total = sum(self.mu[k] * self._S(y // k, u) for k in range(1, y // u + 1))
        self.cache[y] = total
        return total

    def _S(self, y: int, u: int) -> int:
        nu, k = isqrt(y), y // (isqrt(y) + 1)
        hyper = sum(self.M(y // n) for n in range(y // u + 1, k + 1))
        sq = sum((y // n) * self.mu[n] for n in range(1, nu + 1))
        return 1 - hyper + k * self.M(nu) - sq


def main() -> None:
    for x in [1000, 5000, 20000, 100000]:
        ev = MertensEvaluator(x)
        got = ev.M(x)
        direct = sum(moebius_sieve(x)[1:])
        print(f"M({x}) recursion={got} direct={direct} match={got == direct}")


if __name__ == "__main__":
    main()

